def negatives_and_zero(numbers):
    return [n for n in numbers if n < 0]

print(negatives_and_zero([-4, -3, -2, -1, 0, 2, 4, 6]))

solution.code:
def negatives_and_zero(numbers):
    return [n for n in numbers if n <= 0]

print(negatives_and_zero([-4, -3, -2, -1, 0, 2, 4, 6]))

