exercises.starter_code:
def sort_by_price(products):
    return sorted(products, key=lambda p: p[0])

print(sort_by_price([('defter', 45), ('kalem', 12)]))

solution.code:
def sort_by_price(products, descending=False):
    return sorted(products, key=lambda p: p[1], reverse=descending)

print(sort_by_price([('defter', 45), ('kalem', 12)]))

def top_student(students):
    if not students:
        return None
    return max(students, key=lambda s: s[1])[0]
